const loginView=document.querySelector('#login-view'),dashboard=document.querySelector('#dashboard-view'),loginForm=document.querySelector('#login-form'),loginError=document.querySelector('#login-error'),list=document.querySelector('#list'),summary=document.querySelector('#summary'),dashboardError=document.querySelector('#dashboard-error'),passwordModal=document.querySelector('#password-modal'),passwordForm=document.querySelector('#password-form'),passwordMessage=document.querySelector('#password-message'),conversationPane=document.querySelector('#conversation-pane');let selectedStatus='__NAO_RESPONDIDAS__',currentUser=null;
const labels={PENDENTE:'Pendente',GEROU_ORCAMENTO:'Orçamento gerado',ATRIBUIDO_MONTADOR:'Montador atribuído',SERVICO_FINALIZADO:'Serviço finalizado'};const money=c=>c==null?'—':(Number(c)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const date=v=>v?new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';function escapeHtml(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function load(){dashboardError.textContent='';list.innerHTML='<div class="empty">Carregando atendimentos…</div>';const url=selectedStatus?`/api/admin/conversations?status=${encodeURIComponent(selectedStatus)}`:'/api/admin/conversations';try{const res=await fetch(url);const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Sessão expirada.');currentUser=data.usuario;const countMap=Object.fromEntries((data.contagens||[]).map(item=>[item.status,item.quantidade]));document.querySelectorAll('[data-count]').forEach(item=>item.textContent=item.dataset.count==='naoRespondidas'?data.naoRespondidas||0:countMap[item.dataset.count]||0);const rows=data.atendimentos||[];summary.textContent=`${rows.length} atendimento${rows.length===1?'':'s'} encontrado${rows.length===1?'':'s'}`;list.innerHTML=rows.length?rows.map(row=>{const unanswered=row.ultimo_tipo_remetente==='CLIENTE'&&row.status!=='SERVICO_FINALIZADO';const canClaim=!row.atendente_id||row.atendente_id===currentUser.id||currentUser.perfil==='ADMINISTRADOR';return `<article data-id="${row.id}" class="attendance-card ${unanswered?'unanswered':''}"><div><h2>Atendimento #${row.numero_atendimento} · ${escapeHtml(row.nome_cliente)}</h2><p>${escapeHtml(row.telefone)} · atualizado em ${date(row.atualizado_em)}</p><p>${row.atendente_nome?`Atendente responsável: ${escapeHtml(row.atendente_nome)}`:'Na fila · aguardando atendente'}</p><p>${row.detalhes_servico?escapeHtml(row.detalhes_servico):'Sem detalhes de serviço informados'} · ${money(row.valor_servico_centavos)}</p></div><div class="card-actions"><span class="status status-${String(row.status||'').toLowerCase()}">${unanswered?'● Não respondida · ':''}${labels[row.status]||escapeHtml(row.status)}</span>${canClaim&&row.atendente_id!==currentUser.id?`<button class="claim-button" data-claim="${row.id}">${currentUser.perfil==='ADMINISTRADOR'&&row.atendente_id?'Transferir para mim':'Assumir atendimento'}</button>`:''}</div></article>`}).join(''):'<div class="empty">Nenhum atendimento neste filtro.</div>'}catch(error){list.innerHTML='';dashboardError.textContent=error.message;if(error.message.includes('Sessão')){dashboard.hidden=true;loginView.hidden=false}}}
async function claim(id){const res=await fetch('/api/admin/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({atendimentoId:id})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Não foi possível assumir.');load()}
loginForm.addEventListener('submit',async e=>{e.preventDefault();loginError.textContent='';const button=loginForm.querySelector('button');button.disabled=true;try{const res=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(loginForm)))});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Não foi possível entrar.');loginView.hidden=true;dashboard.hidden=false;load()}catch(error){loginError.textContent=error.message}finally{button.disabled=false}});
list.addEventListener('click',async e=>{const button=e.target.closest('[data-claim]');if(!button)return;button.disabled=true;try{await claim(button.dataset.claim)}catch(error){dashboardError.textContent=error.message;button.disabled=false}});document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(item=>item.classList.remove('active'));button.classList.add('active');selectedStatus=button.dataset.status;load()}));document.querySelector('#refresh').addEventListener('click',load);document.querySelector('#logout').addEventListener('click',async()=>{await fetch('/api/admin/logout',{method:'POST'});dashboard.hidden=true;loginView.hidden=false});document.querySelector('#change-password').addEventListener('click',()=>{passwordForm.reset();passwordMessage.textContent='';passwordMessage.className='error';passwordModal.hidden=false});document.querySelector('#close-password').addEventListener('click',()=>passwordModal.hidden=true);passwordModal.addEventListener('click',e=>{if(e.target===passwordModal)passwordModal.hidden=true});passwordForm.addEventListener('submit',async e=>{e.preventDefault();passwordMessage.textContent='';const data=Object.fromEntries(new FormData(passwordForm));if(data.novaSenha!==data.confirmacao){passwordMessage.textContent='A confirmação não coincide com a nova senha.';return}const button=passwordForm.querySelector('button[type=submit]');button.disabled=true;try{const res=await fetch('/api/admin/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await res.json().catch(()=>({}));if(!res.ok)throw new Error(result.error||'Não foi possível trocar a senha.');passwordMessage.className='success';passwordMessage.textContent='Senha alterada com sucesso.';passwordForm.reset()}catch(error){passwordMessage.textContent=error.message}finally{button.disabled=false}});
list.addEventListener('click',e=>{const card=e.target.closest('.attendance-card');if(!card||e.target.closest('[data-claim]'))return;openConversation(card.dataset.id)});
async function openConversation(id){conversationPane.innerHTML='<div class="conversation-empty"><p>Carregando conversa…</p></div>';try{const res=await fetch(`/api/admin/conversation?id=${encodeURIComponent(id)}`);const data=await res.json();if(!res.ok)throw new Error(data.error||'Não foi possível abrir a conversa.');const a=data.atendimento;conversationPane.innerHTML=`<header class="conversation-head"><h2>Atendimento #${a.numero_atendimento} · ${escapeHtml(a.nome_cliente)}</h2><p>${escapeHtml(a.telefone)} · ${a.atendente_nome?`Responsável: ${escapeHtml(a.atendente_nome)}`:'Na fila'}</p></header><div class="conversation-messages">${(data.mensagens||[]).map(m=>`<div class="admin-message ${m.tipo_remetente==='ATENDENTE'?'from-staff':''}">${m.anexo_id?'<span>Imagem anexada</span>':escapeHtml(m.texto||'')}<small>${m.tipo_remetente} · ${date(m.criado_em)}</small></div>`).join('')}</div><form class="conversation-form"><input name="texto" placeholder="Digite uma resposta para o cliente…" maxlength="2000" required><button>Enviar</button></form>`;const messages=conversationPane.querySelector('.conversation-messages');messages.scrollTop=messages.scrollHeight;conversationPane.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const input=e.currentTarget.elements.texto;const button=e.currentTarget.querySelector('button');button.disabled=true;try{const send=await fetch('/api/admin/message',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({atendimentoId:id,texto:input.value})});const result=await send.json();if(!send.ok)throw new Error(result.error||'Não foi possível enviar.');input.value='';openConversation(id);load()}catch(error){dashboardError.textContent=error.message}finally{button.disabled=false}})}catch(error){conversationPane.innerHTML=`<div class="conversation-empty"><p class="error">${escapeHtml(error.message)}</p></div>`}}



const searchInput=document.querySelector('#search');const clearSearch=document.querySelector('.search-clear');searchInput?.addEventListener('input',()=>{const term=searchInput.value.trim().toLowerCase();document.querySelectorAll('.attendance-card').forEach(card=>{card.hidden=term&&!card.textContent.toLowerCase().includes(term)})});clearSearch?.addEventListener('click',()=>{searchInput.value='';searchInput.dispatchEvent(new Event('input'))});

const queueTitle=document.querySelector('#queue-title');document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{if(queueTitle)queueTitle.textContent=button.querySelector('span')?.textContent||''}));
